String noKeyHint(
  String? entryKey,
  String baseUrl,
  ProviderSpec? spec,
  String scopedName,
  List<String> names,
) {
  final suggested =
      entryKey ??
      (baseUrl != spec?.defaultBaseUrl ? scopedName : names.first);
