/// slot. Unreferenced entries contribute nothing.
Set<String> _referencedCustomKeyNames(
  ModelRolesConfig rolesConfig,
  List<CustomProviderEntry> customProviders,
) {
  final named = {
    for (final ref in _rolesChainRefs(rolesConfig))
