  return {
    for (final entry in customProviders)
      if (named.contains(entry.name.toLowerCase())) ...[
        if (entry.keyName != null) entry.keyName!,
        CustomProviderRegistry.keyNameFor(entry.baseUrl),
      ],
  };
}

