            baseUrl: ref.baseUrl!,
            providerName: null,
            // An explicitly pinned ref migrates onto ITS slot (the pin
            // is the contract surface); unpinned refs onto the
            // endpoint's canonical slot.
            pinnedKeyName: ref.apiKeyName,
