/// Step 2 — base URL: Enter applies the shown default (the spec's hosted
/// URL on add, the entry's current URL on edit). Returns null on abort
/// (cancelled or invalid — the message is already printed).
Future<String?> _askBaseUrl(
  CliIO io,
  CustomProviderFlowConfig config,
  ProviderSpec spec,
  void Function() cancelled,
) async {
  final urlDefault = config.initialBaseUrl ?? spec.defaultBaseUrl;
  final urlAnswer = await config.askLine('base URL (empty = $urlDefault): ');
  if (urlAnswer == null) {
    cancelled();
    return null;
  }
  final baseUrl = (urlAnswer.trim().isEmpty ? urlDefault : urlAnswer.trim())
      .replaceAll(RegExp(r'/+$'), '');
  if (!baseUrl.startsWith('http://') && !baseUrl.startsWith('https://')) {
    io.writeln(
      'invalid base URL: ${urlAnswer.trim()} (want http(s)://...) — '
      'setup aborted',
    );
    return null;
  }
  return baseUrl;
}

/// Step 3 — display name: Enter keeps the host-derived default (or the
/// entry's current name on edit). Custom names distinguish entries that
/// share one URL (different keys/accounts). Returns null on cancel.
Future<String?> _askProviderName(
  CustomProviderFlowConfig config,
  String baseUrl,
  void Function() cancelled,
) async {
  final nameDefault = config.initialName ?? config.deriveName(baseUrl);
  var question = 'provider name (empty = $nameDefault): ';
  while (true) {
    final nameAnswer = await config.askLine(question);
    if (nameAnswer == null) {
      cancelled();
      return null;
    }
    final name = nameAnswer.trim().isEmpty ? nameDefault : nameAnswer.trim();
    // Issue #221 ghost guard: a saved entry named after a built-in
    // provider shadows `/provider <name>` routing (the connect flow's
    // name prompt rejects these already — the wizard did not).
    if (providerCatalog.containsKey(name.toLowerCase())) {
      question =
          '"$name" is a built-in provider name — pick another '
          '(empty = $nameDefault): ';
      continue;
    }
    // Issue #555: junk names (`?`, spaces, yaml indicators) either break
    // `/provider <name>` routing or corrupt the bare config.yaml scalar —
    // retry instead of saving.
    if (!isUsableCustomProviderName(name)) {
      question =
          '"$name" is not a usable provider name — use letters, digits, '
          'and . _ + - @ : (empty = $nameDefault): ';
      continue;
    }
    return name;
  }
}

