// Shared fakes and helpers for the agent_cli test suite.

// The scripted-stream half (test model, turn builders, fake stream) lives
// in the suite-neutral harness; re-exported so the suite's consumers keep
// this one import. The file's own remaining members (Abortable's abort
// turn) use it too.
export '../support/scripted_stream_harness.dart';
import '../support/scripted_stream_harness.dart';

import 'dart:async';

import 'package:flutter_agent_harness/flutter_agent_harness.dart';
import 'package:test/test.dart';

/// A [StreamFunction] turn that hangs until cancelled, then reports aborted.
class AbortableStreamFunction {
  var started = false;

  AssistantMessageEventStream call(
    Model model,
    Context context, {
    CancelToken? cancelToken,
  }) {
    started = true;
    final stream = AssistantMessageEventStream();
    stream.push(StartEvent(partial: testAssistant()));
    cancelToken?.onCancel.then((_) {
      stream.push(
        ErrorEvent(
          reason: StopReason.aborted,
          error: testAssistant(
            stopReason: StopReason.aborted,
            errorMessage: 'Operation aborted',
          ),
        ),
      );
      stream.end();
    });
    return stream;
  }
}

/// A [Shell] that blocks until [release] completes the gate.
class GatedShell implements Shell {
  final _gate = Completer<void>();

  void release() => _gate.complete();

  @override
  Future<Result<ShellExecResult, ExecutionError>> exec(
    String command, {
    ShellExecOptions? options,
  }) async {
    await _gate.future;
    return const Ok(ShellExecResult(stdout: '', stderr: '', exitCode: 0));
  }
}

/// A [Shell] that echoes the command and returns canned output.
class FakeShell implements Shell {
  FakeShell({this.stdout = '', this.stderr = '', this.exitCode = 0});

  final String stdout;
  final String stderr;
  final int exitCode;
  final commands = <String>[];
  ShellExecOptions? lastOptions;

  @override
  Future<Result<ShellExecResult, ExecutionError>> exec(
    String command, {
    ShellExecOptions? options,
  }) async {
    commands.add(command);
    lastOptions = options;
    return Ok(
      ShellExecResult(stdout: stdout, stderr: stderr, exitCode: exitCode),
    );
  }
}

/// In-memory [CliIO]: scripted input lines, captured output.
class FakeCliIO implements CliIO {
  @override
  int columns = 80;

  @override
  int rows = 24;

  final _lines = StreamController<String>();
  final _interrupts = StreamController<void>.broadcast();
  final _keys = StreamController<KeyEvent>.broadcast();
  final out = StringBuffer();

  /// Tests flip this to exercise the non-interactive approval path.
  @override
  bool isInteractive = true;

  @override
  Stream<String> get lines => _lines.stream;

  @override
  Stream<void> get interrupts => _interrupts.stream;

  @override
  Stream<KeyEvent> get keys => _keys.stream;

  @override
  bool get supportsRawMode => true;

  @override
  void write(String text) => out.write(text);

  @override
  void writeln(String text) => out.write('$text\n');

  void sendLine(String line) => _lines.add(line);

  void sendKey(KeyEvent key) => _keys.add(key);

content.text:
  final _promptLineBuffer = <String>[];

  /// Runtime secrets granted via `request_secret`.
  final Map<String, String> _runtimeSecrets = {};

  var _diagnosticLogDirEnsured = false;

  /// Size cap of the shared diagnostics log (`~/.fah/logs/fa.log`): on the
  /// first write of a process, an oversized log rotates to `fa.log.1`.
  /// The memory package's print sink (gh-1510) appends prompt-sized debug
  /// lines per memory op, so the append-only design now needs a bound —
  /// without one, an active-memory session grows fa.log far faster than
  /// the pre-existing lifecycle lines ever did.
  @visibleForTesting
  static const diagnosticLogMaxBytes = 4 * 1024 * 1024;

  String? _activeCustomName;
  Completer<String?>? _wizardPickerAnswer;
}

/// One AC3 post-tool narration segment (gh-1433): the text deltas that
/// streamed after ONE tool-call block of the current message. [toolCallId]
/// is stamped by the block's `ToolCallEndEvent` — the same id the
/// execution events carry — so the segment flushes after that call's
/// result row (positional even for parallel/multi-call messages).
final class _PostToolNarrationHold {
  /// The held narration deltas, in stream order.
  final StringBuffer text = StringBuffer();

  /// The tool call this segment follows; null until the call's
  /// `ToolCallEndEvent` stamps it (or never, on a degenerate stream).
  String? toolCallId;
}

