// a synchronous session cache — every later lookup (startup resolution,
// the banner, `/provider`, `/key`) hits the snapshot.
//
// gh-1059: the preload report feeds the boot diagnostics — every read
// logged under --debug-secrets / FA_DEBUG_KEYS, and a config that
// references store keys while NONE resolve prints a warning instead of
// the silent keyless boot.
final keyCache = SecureKeyCache(platformSecureKeyStore());
final keyPreloadReport = await keyCache.preload(
  secureKeyPreloadNames(saved, baseUrl: baseUrl),
);
for (final line in secureKeyBootDiagnostics(
  report: keyPreloadReport,
  referencedKeyNames: referencedSecureKeyNames(saved),
  debug:
      parsed.debugSecrets ||
      isTruthyEnvValue(Platform.environment['FA_DEBUG_KEYS']),
  storeLabel: keyCache.label,
)) {
  stderr.writeln(line);
}

// gh-1679: slots whose key never reached the durable store must not
// masquerade as saved — the wizard's persisted `keyNotPersisted` marker
// (plus any in-process save degradations) renders one boot line per
// affected slot with the retry command, on stderr like every boot
// diagnostic (never stdout — the headless events channel rule).
for (final line in secureKeySaveDegradationLines(
  keys: keyCache,
  customProviders: saved.customProviders,
)) {
  stderr.writeln(line);
}

// gh-1570 incident REG: a key-slot derivation change must never strand
// stored keys. Copy legacy cross-spelling slots onto the canonical slot
// (non-destructive, keychain in scope) BEFORE any resolution runs, and
// surface the per-move notices on stderr (never stdout — the headless
// events channel rule).
for (final line in await migrateLegacyKeySlots([
  for (final entry in saved.customProviders)
    (
      baseUrl: entry.baseUrl,
      providerName: entry.name,
      pinnedKeyName: entry.keyName,
    ),
  if (saved.modelRoles case final roles?)
    for (final chain in [
      ...roles.roles.values,
      for (final override in roles.pathOverrides) ...override.roles.values,
    ])
      for (final ref in chain)
        if (ref.baseUrl != null)
          (
            baseUrl: ref.baseUrl!,
            providerName: null,
            // An explicitly pinned ref migrates onto ITS slot (the pin
            // is the contract surface); unpinned refs onto the
            // endpoint's canonical slot.
            pinnedKeyName: ref.apiKeyName,
          ),
], keyCache)) {
  stderr.writeln(line);
}

// gh-1000 (E2): when the boot-pinned key slot exists in BOTH the
// environment and the store with different values, note the provenance
// order (the env value wins). Detection + wording are the shared
// envShadowingNote rule (key_status.dart) — the restore note and the
// banner hint use the same one.
