  final keyAnswer = await config.askLine(
    'API key (empty for none): ',
    secret: [REDACTED:Sensitive Value],
  );
  if (keyAnswer == null) {
    cancelled();
    return (aborted: true, token: [REDACTED:Sensitive Value]);
  }
  final key = keyAnswer.trim();
  return (aborted: false, token: [REDACTED:Sensitive Value] ? key : null);
}

