List<String> secureKeyBootDiagnostics({
  required SecureKeyPreloadReport report,
  required Set<String> referencedKeyNames,
  required bool debug,
  String? storeLabel,
}) {
  final lines = <String>[];
  final label = storeLabel ?? 'secure store';
