  if (storedHint != null) return storedHint;
  if (onDefaultEndpoint) {
    // Legacy env-name store key (older versions wrote these).
    final legacy = names
        .where((name) => (envVarValue?.call(name) ?? '').isNotEmpty)
        .firstOrNull;
