  void cancelled() => io.writeln(
    editing ? 'provider edit cancelled' : 'custom provider setup cancelled',
  );

  io.writeln(
    editing
        ? 'editing provider ${config.editName} (Ctrl-C to cancel)'
        : 'custom provider setup (Ctrl-C to cancel)',
  );

  // 1. Api type (menu).
