/// manual-entry option), manual entry otherwise; empty keeps the default.
Future<({bool aborted, String modelId})> _askModelId(
  CliIO io,
  CustomProviderFlowConfig config,
  ProviderSpec spec,
  String baseUrl,
  String? token,
  void Function() cancelled,
