    test('the flag survives a yaml round-trip; unset stays byte-absent',
        () {
      final flagged = CustomProviderEntry(
        name: 'kimi_ira',
        apiType: 'openai',
        baseUrl: 'https://api.kimi.com/coding/v1',
        modelId: 'k2',
        keyName: 'FA_KEY_API_KIMI_COM_KIMI_IRA',
        keyNotPersisted: true,
