        baseUrl: 'https://api.kimi.com/coding/v1',
        modelId: 'k2',
        keyName: 'FA_KEY_API_KIMI_COM_KIMI_ME',
      );
      expect(plain.toYaml(), isNot(contains('keyNotPersisted')));
      expect(CustomProviderEntry.fromYaml(plain.toYaml()).keyNotPersisted,
          isFalse);
    });
