String? _storedValueFor(
  String? baseUrl,
  bool customEndpoint,
  String provider,
  SecureKeyCache keys, {
  Iterable<String>? scopedKeyNames,
}) {
  if (baseUrl != null) {
    final stored = _firstStoredValue([
      CustomProviderRegistry.keyNameFor(baseUrl),
      ...?scopedKeyNames,
    ], keys);
    if (stored != null) return stored;
  }
