    /// Drives the edit wizard opened for [entry]: api type → keep (1),
    /// base URL → keep, name → [nameAnswer], key → EMPTY (no save
    /// attempt), model → keep.
    Future<void> runEditWizard({
      required String entryName,
      required String entryBaseUrl,
