}) async {
  final manual = await config.askLine(
    "${prefix}model id (empty keeps '$modelId'): ",
  );
  if (manual == null) {
    cancelled();
    return (aborted: true, modelId: modelId);
  }
  final answer = manual.trim();
  return (aborted: false, modelId: answer.isNotEmpty ? answer : modelId);
}

