    // FA_KEY_API_AIIN_BY / FA_KEY_API_Z_AI, not ..._API_AIIN_BY /
    // ..._Z_AI_Z_AI.
    return name == null ||
            name.isEmpty ||
            name == sanitized ||
            sanitized.endsWith('_$name')
        ? base
        : '${base}_$name';
  }

