      expect(lines[0], contains('FA_KEY_A'));
      expect(lines[1], contains('FA_KEY_B'));
      for (final line in lines) {
        expect(line, contains('fake store'));
        expect(line, contains('keychain write failed (exit 45)'));
        expect(line, contains('/key set'));
