/// The manual model-id prompt shared by every fallback path; an empty
/// answer keeps [modelId].
Future<({bool aborted, String modelId})> _askManualModelId(
  CustomProviderFlowConfig config,
  String modelId,
  void Function() cancelled, {
  String prefix = '',
}) async {
