    final uri = Uri.tryParse(baseUrl);
    final sanitized = _sanitizeKeyHost(_hostWithPort(uri, baseUrl));
    final base = 'FA_KEY_${sanitized.isEmpty ? 'CUSTOM' : sanitized}';
