      return _askLineTui(tui, question, secret);
    }
    return _promptLine(question);
  }

  /// The TUI branch of [_askLine].
  Future<String?> _askLineTui(
    FaTuiController tui,
    String question,
    bool secret,
  ) async {
    final spec = TextPromptSpec(
      question: question,
