  _MapStore({this.availability = true});

  bool availability;
  bool failWrites = false;
  final map = <String, String>{};

  @override
  String get label => 'fake store';

  @override
  Future<bool> isAvailable() async => availability;

  @override
  Future<String?> read(String name) async => map[name];

