      final advisory = missingDefaultKeychainAdvisory();
      // The remedy command is named, never executed (pure string).
      expect(
        advisory,
        contains(
          'security default-keychain -s ~/Library/Keychains/login.keychain-db',
        ),
      );
      expect(advisory, startsWith('note:'));
    });
  });
}

