      io.sendLine(nameAnswer);
      await waitForIt(
        () => io.out.toString().contains('API key (empty for none):'),
      );
      io.sendLine(''); // no fresh token — the store-independent edit
      await waitForIt(
        () => io.out.toString().contains('model id (empty keeps'),
      );
      io.sendLine('');
      await waitForIt(
